// Le declencheur est lu par son NOM : le predecesseur immediat est Config.
const recu = $('🔔 Webhook: decision de Lineo').first().json ?? {};
const body = recu.body ?? {};
const query = recu.query ?? {};

const id = String(query.id ?? body.id ?? '').trim();
if (!id) {
  throw new Error("decision sans id : impossible de savoir quelle candidature envoyer. URL attendue : .../webhook/candidature-decision?id=<id de la fiche>");
}

const DECISIONS = ['valider', 'retoucher_lettre', 'retoucher_cv', 'refuser'];
const decision = String(body.decision ?? '').trim().toLowerCase();

return [{
  json: {
    inboxId: id,
    inboxPath: 'data-inbox/' + id + '.json',
    // Une decision inconnue n'est PAS traduite en refus ni en validation : elle
    // part en alerte. Deviner ici, c'est envoyer un courriel que personne n'a
    // demande, ou en jeter un que Lineo attendait.
    decision: DECISIONS.includes(decision) ? decision : '',
    decisionBrute: decision,
    consigne: String(body.consigne ?? '').trim().slice(0, 600),
    raison: String(body.raison ?? '').trim().slice(0, 600),
    decidePar: String(body.decide_par ?? '').trim(),
    decideLe: new Date().toISOString(),
  },
}];

const dec = $('🧩 Decision recue').first().json;
const file = $json ?? {};

let fiche;
try {
  fiche = JSON.parse(Buffer.from(String(file.content || '').replace(/\n/g, ''), 'base64').toString('utf8'));
} catch (e) {
  throw new Error('fiche ' + dec.inboxPath + ' illisible : ' + e.message);
}
if (!fiche || !String(fiche.schema || '').startsWith('career-ops-inbox/')) {
  throw new Error(dec.inboxPath + " n'est pas une fiche career-ops : rien ne sera envoye");
}
if (!fiche.branche_github) {
  throw new Error('fiche sans branche_github : le CV et la lettre sont introuvables');
}

return [{
  json: {
    ...dec,
    fiche,
    ficheSha: file.sha || '',
    ficheRevision: Number(fiche.revision || 0),
    branchName: String(fiche.branche_github),
    courrielContact: String(fiche.courriel_contact || '').trim(),
  },
}];

// Le CV et la lettre sont relus depuis la BRANCHE, pas depuis une memoire du
// workflow 2 : entre la generation et la decision, il peut s'etre ecoule des
// jours et un round de retouche. Ce qui part est ce qui est sur la branche.
const ctx = $('🧩 Decision: contexte').first().json;

const bin = {};
try {
  const b = $('📥 CV PDF de la branche').first().binary || {};
  if (b.data) bin.data = { ...b.data, fileName: 'cv-BIRIBIN-LINEO.pdf', fileExtension: 'pdf' };
} catch (e) { /* absent */ }
try {
  const b = $('📥 Lettre DOCX de la branche').first().binary || {};
  if (b.docx) bin.docx = { ...b.docx, fileName: 'lettre-BIRIBIN-LINEO.docx', fileExtension: 'docx' };
} catch (e) { /* absent */ }

// Aucun CV = on n'envoie rien. Une candidature sans piece jointe chez un
// recruteur est pire qu'une candidature en retard.
if (!bin.data) {
  throw new Error('aucun CV PDF sur la branche ' + ctx.branchName + " : rien n'a ete envoye");
}

const pieces = ['CV PDF adapte au poste'];
if (bin.docx) pieces.push('lettre de motivation Word (1 page)');

return [{
  json: {
    ...ctx,
    attachmentNames: pieces.join(' + '),
    attachmentProps: [bin.data ? 'data' : null, bin.docx ? 'docx' : null].filter(Boolean).join(','),
  },
  binary: bin,
}];

// Archive avant suppression : la branche cv/<entreprise>-<poste>-<id> porte le CV
// et la lettre exacts recus par le recruteur. Un tag annote sent/<entreprise>-<date>
// est pose sur son dernier commit pour que l'arbre survive a la suppression.
//
// Le contexte est lu dans « Contact retenu », PAS dans « Joindre CV + lettre » :
// c'est le premier des deux qui porte l'adresse retenue quand elle vient de
// l'enrichissement. Lire l'autre archivait un destinataire vide.
const cfg = $('⚙️ Config').first().json;
const ctx = $('🧩 Contact retenu').first().json;
const fiche = ctx.fiche ?? {};

// Meme convention de slug que career-ops/application-artifacts.mjs et que la
// branche cv/<slug>-<poste>-<id> : le <slug> de sent/<slug> reprend le sien.
const slugify = (value) => String(value || 'unknown')
  .normalize('NFD')
  .replace(/\p{Diacritic}/gu, '')
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '')
  .slice(0, 40) || 'unknown';

const sentDate = $now.setZone('Europe/Paris').toFormat('yyyy-MM-dd');

return [{
  json: {
    githubOwner: cfg.githubOwner,
    githubRepo: cfg.githubRepo,
    token: cfg.githubToken,
    branchName: ctx.branchName,
    inboxId: ctx.inboxId,
    company: String(fiche.entreprise || ''),
    tagBase: 'sent/' + slugify(fiche.entreprise || 'entreprise') + '-' + sentDate,
    sentDate,
    recipient: String(ctx.courrielContact || cfg.candidateEmail || ''),
    contactSource: String(ctx.contactSource || ''),
    contactConfiance: String(ctx.contactConfiance || ''),
    // Sortie du noeud Gmail qui precede : le seul lien fiable message <-> candidature.
    // threadId part aussi en base (career_ops.candidature.fil_gmail), ce qui permet
    // au workflow 4 d'apparier une reponse de recruteur par fil.
    gmailMessageId: String($json.id || ''),
    gmailThreadId: String($json.threadId || ''),
    jobTitle: String(fiche.poste || ''),
    jobUrl: String(fiche.url_offre || ''),
    pdfPath: cfg.githubPdfPath,
    docxPath: cfg.githubLetterDocxPath,
  },
}];

// Corps du tag annote. Son message est ce que Lineo relira dans 3 mois :
//   git show <tag>                        -> metadonnees de la candidature
//   git show <tag>:dist/pdf/cv-fr-ats.pdf -> le CV exact envoye
const prep = $('🧩 Preparer le tag archive').first().json;
const cfg = $('⚙️ Config').first().json;
const existing = $('🐙 GitHub: Tags archive existants').first().json.body;
const headSha = $json.object && $json.object.sha ? String($json.object.sha) : '';

// Garde-fou : pas de SHA archivable => on jette. La suppression de branche etant
// en aval, elle n'est jamais atteinte et la branche survit pour inspection.
if (!headSha) {
  throw new Error('HEAD de la branche ' + prep.branchName + ' introuvable : archivage impossible, la branche est conservee');
}

// Deux candidatures chez la meme entreprise le meme jour : POST /git/refs renvoie
// 422 « Reference already exists ». On suffixe -2, -3... d'apres les tags poses.
const taken = Array.isArray(existing) ? existing.length : 0;
const archiveTag = taken === 0 ? prep.tagBase : prep.tagBase + '-' + (taken + 1);

const message = [
  'Candidature envoyee - ' + (prep.company || 'entreprise inconnue'),
  '',
  'Poste        : ' + (prep.jobTitle || ''),
  'Entreprise   : ' + (prep.company || ''),
  'Offre        : ' + (prep.jobUrl || ''),
  'Destinataire : ' + (prep.recipient || '')
    + (prep.contactSource ? ' (source : ' + prep.contactSource
        + (prep.contactConfiance ? ', confiance ' + prep.contactConfiance : '') + ')' : ''),
  'Envoye le    : ' + prep.sentDate,
  '',
  'Branche d origine : ' + prep.branchName,
  'Fiche inbox       : ' + (prep.inboxId || ''),
  'CV joint          : ' + (prep.pdfPath || ''),
  'Lettre jointe     : ' + (prep.docxPath || ''),
  'Message Gmail     : ' + (prep.gmailMessageId || ''),
  'Fil Gmail         : ' + (prep.gmailThreadId || ''),
  '',
  'Tag pose par le workflow n8n 3 (Envoi et relances) avant suppression de la branche.',
  'Recuperer : git fetch origin --tags puis git show ' + archiveTag + ':' + (prep.pdfPath || ''),
].join('\n');

const tagBody = {
  tag: archiveTag,
  message,
  object: headSha,
  type: 'commit',
  tagger: {
    name: cfg.candidateName || 'career-ops',
    email: cfg.candidateEmail || '',
    date: new Date().toISOString(),
  },
};

return [{ json: { ...prep, archiveTag, archiveCommitSha: headSha, tagBodyRaw: JSON.stringify(tagBody) } }];

// Retouche : on renvoie la candidature au workflow 2 avec la consigne libre de
// Lineo. Le ficheId et la BRANCHE sont repris tels quels : le workflow 2 committe
// alors sur la meme branche cv/<...> et incremente la revision. Une branche neuve
// perdrait le round precedent.
const ctx = $('🧩 Decision: contexte').first().json;
const fiche = ctx.fiche ?? {};
const rep = $json ?? {};

const offres = Array.isArray(rep.offres) ? rep.offres : [];
const jobId = String(fiche.job_id || '').trim();

// Appariement par job_id, la seule cle stable. Repli sur entreprise + poste
// normalises, parce qu'une fiche v1 (avant l'ajout de job_id) n'en a pas.
const norm = (s) => String(s || '')
  .normalize('NFD').replace(/\p{Diacritic}/gu, '')
  .toLowerCase().replace(/\s+/g, ' ').trim();

let offre = null;
if (jobId) offre = offres.find((o) => String(o.jobId ?? o.id ?? '').trim() === jobId) || null;
if (!offre) {
  offre = offres.find((o) => norm(o.company) === norm(fiche.entreprise)
    && norm(o.title) === norm(fiche.poste)) || null;
}

const cible = ctx.decision === 'retoucher_cv' ? 'cv' : 'lettre';

const job = {
  jobId: jobId || String(offre?.jobId ?? ''),
  title: String(offre?.title || fiche.poste || ''),
  company: String(offre?.company || fiche.entreprise || ''),
  location: offre?.location ?? fiche.lieu ?? null,
  url: String(offre?.url || fiche.url_offre || ''),
  description: String(offre?.description || ''),
  whyMatch: String(offre?.whyMatch || fiche.pourquoi_ca_matche || ''),
  contactEmail: String(ctx.courrielContact || ''),
  score: offre?.score ?? fiche.score ?? null,
};

// Le workflow 2 refuse une offre sans title NI description : on echoue ici, ou le
// message est lisible, plutot que dans un 400 au milieu de sa chaine.
if (!job.title && !job.description) {
  throw new Error('retouche impossible : offre ' + (jobId || '(sans job_id)')
    + ' introuvable dans /api/offers et fiche sans poste. Rien n a ete renvoye au workflow 2.');
}

const charge = {
  mode: 'retouche',
  ficheId: ctx.inboxId,
  branche: ctx.branchName,
  consigne: ctx.consigne,
  cible,
  job,
};

return [{
  json: {
    cible,
    // Sans description, le workflow 2 readapte sur le seul intitule : c'est moins
    // bon, et ca doit se voir dans l'execution plutot que se deviner.
    offreRetrouvee: Boolean(offre),
    descriptionDisponible: Boolean(job.description),
    ficheId: ctx.inboxId,
    branche: ctx.branchName,
    consigne: ctx.consigne,
    wf2PayloadRaw: JSON.stringify(charge),
  },
}];

// Contrat gele : GET /api/followups?full=1
//   -> { due: [ { id, entreprise, poste, courriel_contact, jours_depuis_envoi } ],
//        cadenceConfig: { applied_first, applied_max_followups, ... } }
// La cadence de relance (delai, nombre maxi) est une valeur de CONFIG career-ops,
// pas une constante inventee ici. Ordre de priorite : cadenceConfig de l'API,
// puis les valeurs de repli de « Config relances », puis les defauts documentes.
// L'ancienne forme { available, entries: [...] } reste acceptee.
const cfg = $('⚙️ Config relances').first().json;
const rep = $input.first().json ?? {};

// Le noeud HTTP est en onError=continueRegularOutput : un echec reseau arrive
// ici sous forme d'item vide. Zero relance en silence serait PIRE qu'une erreur
// visible : Lineo cesserait de relancer sans jamais l'apprendre. Donc on jette.
if (rep.due === undefined && rep.entries === undefined) {
  throw new Error('GET /api/followups injoignable ou hors contrat. Reponse recue : ' + JSON.stringify(rep).slice(0, 300));
}

const brut = Array.isArray(rep.due) ? rep.due : (Array.isArray(rep.entries) ? rep.entries : []);

// ── Cadence : ce qu'il y a dans la config career-ops fait foi ────────────────
const cc = rep.cadenceConfig ?? rep.metadata?.cadenceConfig ?? {};
const premierEntier = (...valeurs) => {
  for (const v of valeurs) {
    const n = Number(v);
    if (Number.isFinite(n) && n > 0) return Math.floor(n);
  }
  return null;
};
const relanceDelaiJours = premierEntier(
  cc.applied_first_days, cc.appliedFirstDays, cc.applied_first, cc.first_days,
  cfg.relanceSeuilJours, 7,
);
const relanceMax = premierEntier(
  cc.applied_max_followups, cc.appliedMaxFollowups, cc.max_followups, cc.applied_max,
  cfg.relanceMax, 2,
);
const cadenceSource = premierEntier(cc.applied_first_days, cc.appliedFirstDays, cc.applied_first, cc.first_days)
  ? 'config career-ops (/api/followups?full=1)'
  : 'repli : valeurs par defaut documentees';

const maxi = premierEntier(cfg.maxRelancesParExecution, 3);

const slug = (v) => String(v || '')
  .normalize('NFD').replace(/\p{Diacritic}/gu, '')
  .toLowerCase().replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '').slice(0, 40);

const retenues = [];
for (const e of brut) {
  const entreprise = String(e.entreprise ?? e.company ?? '').trim();
  const poste = String(e.poste ?? e.role ?? e.title ?? '').trim();
  // Sans entreprise on ne sait ni quoi ecrire, ni quoi retrouver dans le tracker.
  if (!entreprise) continue;
  const jours = Number(e.jours_depuis_envoi ?? e.daysSinceApplied ?? NaN);
  // Un champ absent passe volontairement : c'est la cadence career-ops qui fait
  // foi, on ne re-filtre que quand la valeur existe vraiment.
  if (Number.isFinite(jours) && jours < relanceDelaiJours) continue;
  // L'id NE contient PAS de date : c'est la cle de l'historique des relances
  // deja envoyees pour cette candidature. Sans ca, un cron quotidien renverrait
  // la meme relance au recruteur chaque jour.
  retenues.push({
    relanceId: 'relance-' + (slug(entreprise) || 'entreprise') + '-' + (slug(poste) || 'poste'),
    sourceId: String(e.id ?? ''),
    entreprise,
    poste,
    courrielContact: String(e.courriel_contact ?? e.contactEmail ?? '').trim(),
    joursDepuisEnvoi: Number.isFinite(jours) ? jours : null,
    envoyeeLe: String(e.envoyee_le ?? e.appliedAt ?? '').trim(),
    urlOffre: String(e.url ?? e.url_offre ?? '').trim(),
    relanceDelaiJours,
    relanceMax,
    cadenceSource,
    consigneRetouche: '',
  });
}

// Plafond par execution. Rien n'est tronque en silence : le nombre reporte part
// dans le bilan de fin de tournee, et la relance ressortira a la prochaine.
const gardees = retenues.slice(0, maxi);
const reportees = retenues.length - gardees.length;

return gardees.map((r) => ({ json: { ...r, relancesDues: retenues.length, relancesReportees: reportees } }));

// Bilan de fin de tournee. Aucun envoi ici : chaque relance a deja ete tranchee
// automatiquement (envoyee, arretee par une regle de cadence, ou deposee a la main).
const items = $input.all();
return [{
  json: {
    relancesTraitees: items.length,
    finLe: new Date().toISOString(),
  },
}];

// Relances AUTOMATIQUES : pas de porte de validation, pas de recalcul manuel.
// Soit la relance part, soit elle est arretee, et c'est une regle qui tranche.
//
// Les deux bornes viennent de la CONFIG career-ops, remontee par le normaliseur
// (cadenceConfig de /api/followups?full=1) : espacement et nombre maxi.
const rel = $('🔁 Boucle relances').first().json;
const prev = $input.first().json ?? {};

// Historique des relances deja envoyees (404 la premiere fois -> item vide).
let histoire = { relances: [] };
let sha = null;
if (typeof prev.sha === 'string' && prev.sha) {
  sha = prev.sha;
  try {
    const lu = JSON.parse(
      Buffer.from(String(prev.content || '').replace(/\n/g, ''), 'base64').toString('utf8'),
    );
    if (lu && typeof lu === 'object') histoire = lu;
  } catch (e) {
    // Fiche illisible : on la traite comme vide plutot que de bloquer la tournee.
    histoire = { relances: [] };
  }
}

const envoyees = Array.isArray(histoire.relances) ? histoire.relances : [];
const rang = envoyees.length + 1;
const max = Number(rel.relanceMax || 2);
const espacement = Number(rel.relanceDelaiJours || 7);
const histPath = 'data-inbox/relances/' + rel.relanceId + '.json';
const histArret = (histoire && typeof histoire.arret === 'object') ? histoire.arret : null;

// ── ARRET : EN TOUT PREMIER, AVANT LE PLAFOND ET AVANT L'ESPACEMENT ─────────
// Le recruteur a repondu, et c'est le workflow 4 (ecoute Gmail, gVPaJrIaXNqC2ZDP)
// qui l'a inscrit dans ce fichier. Aucune autre regle n'a son mot a dire : ni le
// plafond pas atteint, ni l'espacement respecte. Sans ces lignes, WF4 ecrit dans
// le vide et la tournee du lendemain relance quelqu'un qui a deja repondu.
// `actif !== false` plutot que `=== true` : un fichier corrige a la main avec un
// simple { "arret": { "motif": "..." } } doit arreter la relance aussi. Sur ce
// chemin-la, le doute coupe, il ne laisse pas passer.
// Copie de reference versionnee : n8n/wf3-relance-decider.js du depot cv.
if (histArret && histArret.actif !== false) {
  return [{
    json: {
      ...rel,
      rang,
      envoyable: false,
      motifArret: 'arret : ' + (histArret.motif || 'reponse du recruteur')
        + (histArret.arrete_le ? ' (' + histArret.arrete_le + ')' : ''),
      arretActif: true,
      arretTypeReponse: histArret.type_reponse || '',
      histArret,
      histSha: sha,
      histRelances: envoyees,
      histPath,
    },
    pairedItem: 0,
  }];
}

let envoyable = true;
let motifArret = '';

if (envoyees.length >= max) {
  envoyable = false;
  motifArret = 'plafond atteint : ' + envoyees.length + ' relance(s) deja envoyee(s), maximum ' + max + ' (config career-ops)';
} else {
  const derniere = envoyees[envoyees.length - 1];
  const quand = derniere && derniere.envoyee_le ? Date.parse(derniere.envoyee_le) : NaN;
  if (Number.isFinite(quand)) {
    const jours = Math.floor((Date.now() - quand) / 86400000);
    if (jours < espacement) {
      envoyable = false;
      motifArret = 'derniere relance il y a ' + jours + ' j, espacement minimum ' + espacement + ' j (config career-ops)';
    }
  }
}

return [{
  json: {
    ...rel,
    rang,
    envoyable,
    motifArret,
    arretActif: false,
    arretTypeReponse: '',
    histArret,
    histSha: sha,
    histRelances: envoyees,
    histPath,
  },
  pairedItem: 0,
}];

// POST /api/followup-draft rend { objet, corps, mots, compte } a plat : on le
// raccroche a la relance pour que l'aiguillage et l'envoi aient le destinataire.
const rel = $('🧩 Relance: decider').first().json;
const out = $input.first().json ?? {};

const objet = String(out.objet ?? '').trim();
const corps = String(out.corps ?? '').trim();

// Garde-fou : career-ops a deja ses propres refus (echange invente, duree
// inventee, longueur). Celui-ci ne couvre qu'un cas : une reponse vide ou
// tronquee qui deviendrait un courriel vide chez le recruteur. On prefere une
// tournee en erreur, visible, a un envoi muet.
if (!objet || !corps) {
  throw new Error('brouillon de relance vide pour ' + (rel.entreprise || '?')
    + " : rien n'a ete envoye. Reponse : " + JSON.stringify(out).slice(0, 300));
}

// Nettoyage aligne sur le CV et la lettre : ni tiret cadratin ni markdown.
// career-ops nettoie deja (nettoieRelance), ceci est une ceinture de plus.
const cleanTxt = (s) => String(s || '')
  .replace(/\*\*([^*]+)\*\*/g, '$1')
  .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1')
  .replace(/ [—–] /g, ', ').replace(/[—–]/g, ', ');

return [{
  json: { ...rel, objet: cleanTxt(objet), corps: cleanTxt(corps), mots: out.mots ?? null },
  pairedItem: 0,
}];

// Trace versionnee de ce qui part chez le recruteur, et surtout CLE DE
// DEDUPLICATION de la prochaine tournee : sans ce fichier, un cron quotidien
// renverrait la meme relance chaque jour.
// Sous-dossier data-inbox/relances/ : career-ops ne lit data-inbox/ qu'a plat,
// donc rien n'apparait sur la page « A valider » (ces relances ne se decident
// plus, elles s'envoient).
//
// POURQUOI CE NOEUD EST EN PARALLELE DE L'ENVOI, ET PAS APRES :
// deux tentatives ont echoue le 2026-08-05.
//  - execution 958254, en serie apres Gmail avec .first() : l'historique de la
//    relance B a ete ecrit en y collant le message_id de l'envoi de A. Dans une
//    boucle, .first() rend le premier item du DERNIER run du noeud, pas celui de
//    l'iteration courante.
//  - executions 958257 et 958259, avec .item : le chainage d'items ne se
//    remonte pas a travers le noeud Gmail, quel que soit le mode du noeud Code.
// En branchant ce noeud directement sur la sortie de l'aiguillage, l'item recu
// EST celui de l'iteration : plus aucune recherche inter-noeuds, donc plus aucune
// confusion possible entre deux relances.
//
// Contrepartie assumee : cette branche n'attend pas la confirmation de Gmail,
// donc pas de message_id dans l'historique, et un envoi definitivement en echec
// laisse quand meme la relance marquee comme faite. C'est le sens d'echec le plus
// sur pour un envoi automatique : une relance manquee vaut mieux qu'un doublon
// chez le recruteur. L'envoi a 3 tentatives pour limiter le cas.
const rel = $input.first().json ?? {};
const cfg = $('⚙️ Config relances').first().json;

if (!rel.relanceId) {
  throw new Error("item de relance sans relanceId : rien n'est ecrit dans l'historique");
}

const relances = [
  ...(Array.isArray(rel.histRelances) ? rel.histRelances : []),
  {
    rang: rel.rang,
    envoyee_le: new Date().toISOString(),
    objet: rel.objet,
    destinataire: rel.courrielContact,
    execution_id: String($execution.id),
    jours_depuis_envoi_candidature: rel.joursDepuisEnvoi,
  },
];

const fiche = {
  schema: 'career-ops-relances/v1',
  id: rel.relanceId,
  entreprise: rel.entreprise,
  poste: rel.poste,
  courriel_contact: rel.courrielContact,
  url_offre: rel.urlOffre,
  cadence: {
    espacement_jours: rel.relanceDelaiJours,
    maximum: rel.relanceMax,
    source: rel.cadenceSource,
  },
  relances,
};

// Un arret ecrit par le workflow 4 SURVIT a cette reecriture. Ce noeud
// reconstruit la fiche de zero : sans cette recopie, il effacerait la seule cle
// qui empeche les relances de repartir. On ne devrait pas etre la (le garde de
// « Relance: decider » coupe avant), mais un fichier qui perd sa propre cle
// d'arret est le genre de panne qu'on ne decouvre qu'une fois la relance partie.
if (rel.histArret && typeof rel.histArret === 'object') {
  fiche.arret = rel.histArret;
}

const body = {
  message:
    (rel.histSha ? 'chore(relances): maj ' : 'chore(relances): ') +
    (rel.entreprise || 'entreprise') + ' - relance ' + rel.rang,
  content: Buffer.from(JSON.stringify(fiche, null, 2) + '\n', 'utf8').toString('base64'),
  branch: cfg.githubBaseBranch,
};
if (rel.histSha) body.sha = rel.histSha;

return [{ json: { ...rel, histBodyRaw: JSON.stringify(body) } }];

// Le noeud HTTP qui precede a remplace l'item par sa reponse : les pieces
// jointes assemblees par « Joindre CV + lettre » doivent etre rattachees ici,
// sinon le courriel au recruteur partirait sans CV.
const ctx = $('🧩 Joindre CV + lettre').first().json;
const bin = $('🧩 Joindre CV + lettre').first().binary ?? {};

// neverError + fullResponse : la reponse utile est dans .body, et un echec
// arrive ici sous forme d'item sans body plutot qu'en exception.
const rep = ($json && typeof $json === 'object' && $json.body) ? $json.body : {};

const deLaFiche = String(ctx.courrielContact || '').trim();
const trouve = String(rep.courriel || '').trim();
const confiance = String(rep.confiance || 'aucune');

// Haute  : carnet d'adresses, ou adresse de recrutement sur le domaine de
//          l'entreprise.
// Moyenne: adresse de recrutement, ou boite du domaine de l'entreprise.
// En dessous : l'adresse a bien ete lue quelque part, mais rien ne la relie au
// poste (le prestataire qui heberge la page, par exemple). Envoyer une
// candidature la-dessus est pire que de ne pas l'envoyer : c'est irrattrapable.
const envoyable = trouve !== '' && (confiance === 'haute' || confiance === 'moyenne');

// La fiche gagne toujours : si Lineo a renseigne une adresse a la main,
// l'enrichissement n'a pas a la contredire.
const courrielContact = deLaFiche || (envoyable ? trouve : '');

return [{
  json: {
    ...ctx,
    courrielContact,
    contactSource: deLaFiche ? 'fiche' : (courrielContact ? String(rep.source || 'annonce') : ''),
    contactConfiance: deLaFiche ? 'fiche' : confiance,
    contactMotif: deLaFiche ? 'adresse deja presente sur la fiche' : String(rep.motif || 'recherche non aboutie'),
    contactCandidats: Array.isArray(rep.candidats) ? rep.candidats : [],
    contactSourcesConsultees: Array.isArray(rep.sourcesConsultees) ? rep.sourcesConsultees : [],
  },
  binary: bin,
}];
